import { createContext, useCallback, useContext, useEffect, useMemo, useState, type ReactNode } from 'react';
import type { KeycloakTokenParsed } from 'keycloak-js';
import {
  getKeycloak,
  getToken,
  initKeycloak,
  installAuthenticatedFetch,
  isAuthEnabled,
  login,
  logout as keycloakLogout,
} from '../services/KeycloakService';

type DecodedToken = KeycloakTokenParsed & {
  name?: string;
  given_name?: string;
  family_name?: string;
  preferred_username?: string;
  email?: string;
  sid?: string;
  auth_time?: number;
  role?: string;
  roles?: string[];
  realm_access?: { roles?: string[] };
  resource_access?: Record<string, { roles?: string[] }>;
  groups?: string[];
};

type AuthContextValue = {
  isInitializing: boolean;
  isAuthenticated: boolean;
  accessToken?: string;
  decodedToken?: DecodedToken;
  currentSessionId?: string;
  logout: () => Promise<void>;
  refreshToken: () => Promise<boolean>;
};

const AuthContext = createContext<AuthContextValue | undefined>(undefined);

const sessionIdFromToken = (token?: DecodedToken) => {
  const sessionState = token?.session_state;
  if (typeof sessionState === 'string') return sessionState;
  return token?.sid;
};

export function AuthProvider({ children }: { children: ReactNode }) {
  const authEnabled = isAuthEnabled();
  const [isInitializing, setIsInitializing] = useState(authEnabled);
  const [isAuthenticated, setIsAuthenticated] = useState(!authEnabled);
  const [accessToken, setAccessToken] = useState<string | undefined>();
  const [decodedToken, setDecodedToken] = useState<DecodedToken | undefined>();
  const [currentSessionId, setCurrentSessionId] = useState<string | undefined>();

  const syncAuthState = useCallback(() => {
    const keycloak = getKeycloak();
    const token = keycloak.tokenParsed as DecodedToken | undefined;
    setIsAuthenticated(Boolean(keycloak.authenticated));
    setAccessToken(getToken());
    setDecodedToken(token);
    setCurrentSessionId(sessionIdFromToken(token));
  }, []);

  const clearAuthState = useCallback(() => {
    setIsAuthenticated(false);
    setAccessToken(undefined);
    setDecodedToken(undefined);
    setCurrentSessionId(undefined);
  }, []);

  const refreshToken = useCallback(async () => {
    if (!authEnabled) {
      return true;
    }

    const keycloak = getKeycloak();
    try {
      const refreshed = await keycloak.updateToken(30);
      if (refreshed) {
        syncAuthState();
      }
      return true;
    } catch {
      clearAuthState();
      await login();
      return false;
    }
  }, [authEnabled, clearAuthState, syncAuthState]);

  const logout = useCallback(async () => {
    if (!authEnabled) {
      return;
    }

    try {
      await keycloakLogout();
    } catch (e) {
      console.error('Logout failed', e);
      // Fallback: force navigation to origin
      window.location.href = window.location.origin;
    }
  }, [authEnabled]);
  useEffect(() => {
    if (!authEnabled) {
      installAuthenticatedFetch();
      setDecodedToken({
        preferred_username: 'shaukat',
        roles: ['admin'],
        realm_access: { roles: ['admin'] }
      });
      setIsInitializing(false);
      setIsAuthenticated(true);
      return;
    }

    let cancelled = false;
    let refreshTimer: number | undefined;
    const keycloak = getKeycloak();

    keycloak.onTokenExpired = () => {
      void refreshToken();
    };

    initKeycloak()
      .then(async authenticated => {
        if (cancelled) return;

        if (!authenticated) {
          clearAuthState();
          await login();
          return;
        }

        installAuthenticatedFetch();
        syncAuthState();
        refreshTimer = window.setInterval(() => {
          void refreshToken();
        }, 30000);
      })
      .catch(async () => {
        clearAuthState();
        await login();
      })
      .finally(() => {
        if (!cancelled) {
          setIsInitializing(false);
        }
      });

    return () => {
      cancelled = true;
      keycloak.onTokenExpired = undefined;
      if (refreshTimer) {
        window.clearInterval(refreshTimer);
      }
    };
  }, [authEnabled, clearAuthState, refreshToken, syncAuthState]);

  const value = useMemo<AuthContextValue>(
    () => ({
      isInitializing,
      isAuthenticated,
      accessToken,
      decodedToken,
      currentSessionId,
      logout,
      refreshToken,
    }),
    [accessToken, currentSessionId, decodedToken, isAuthenticated, isInitializing, logout, refreshToken],
  );

  if (isInitializing || !isAuthenticated) {
    return (
      <div className="auth-shell">
        <div className="auth-status">Connecting to Tantor SSO...</div>
      </div>
    );
  }

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used inside AuthProvider');
  }
  return context;
};

import React, { createContext, useContext, useState, useEffect, useMemo } from 'react';

export interface Cluster {
  id: string;
  name: string;
  status: string;
  kafkaVersion: string;
  mode: string;
  [key: string]: any;
}

interface ClusterContextProps {
  clusters: Cluster[];
  activeClusterId: string | null;
  setActiveClusterId: (id: string | null) => void;
  /** The mode of the currently active cluster ('EXTERNAL' or other values like 'kraft') */
  activeClusterMode: string | null;
  /** Convenience boolean: true when the active cluster is External */
  isExternalCluster: boolean;
  loading: boolean;
}

const ClusterContext = createContext<ClusterContextProps>({
  clusters: [],
  activeClusterId: null,
  setActiveClusterId: () => {},
  activeClusterMode: null,
  isExternalCluster: false,
  loading: true,
});

export const useCluster = () => useContext(ClusterContext);

export const ClusterProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [clusters, setClusters] = useState<Cluster[]>([]);
  const [activeClusterId, setActiveClusterId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch('/api/v1/ui/clusters')
      .then(res => res.json())
      .then(data => {
        setClusters(data);
        if (data.length > 0) {
          const defaultCluster = data.find((c: Cluster) => c.status !== 'DELETED') || data[0];
          setActiveClusterId(defaultCluster.id);
        }
      })
      .catch(err => console.error("Failed to load clusters for dropdown", err))
      .finally(() => setLoading(false));
  }, []);

  const activeClusterMode = useMemo(() => {
    if (!activeClusterId) return null;
    const found = clusters.find(c => c.id === activeClusterId);
    return found?.mode ?? null;
  }, [activeClusterId, clusters]);

  const isExternalCluster = activeClusterMode === 'EXTERNAL';

  return (
    <ClusterContext.Provider value={{ clusters, activeClusterId, setActiveClusterId, activeClusterMode, isExternalCluster, loading }}>
      {children}
    </ClusterContext.Provider>
  );
};

