  // Sync the global active cluster context whenever this page loads
  useEffect(() => {
    if (id) setActiveClusterId(id);
  }, [id, setActiveClusterId]);

  useEffect(() => {
    // Clear stale data when switching clusters to prevent flash of old data
    setCluster(null);
