const EXTERNAL_HEALTH_REFRESH_MS = 15000;
import { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { Network, RefreshCw, ExternalLink, Plus } from 'lucide-react';
import { usePermissions } from '../hooks/usePermissions';
import { confirmAction, notifyAction } from '../components/ConfirmDialog';
import { clusterStatusTone } from '../utils/clusterStatusTone';
import './Clusters.css';

interface ClusterHost {
  hostId?: string;
  hostname?: string;
  ipAddress?: string;
  status?: string;
  role?: string;
  lastHeartbeat?: string;
  diskUsedGb?: number;
  diskTotalGb?: number;
  bootstrap?: string;
}

interface ClusterInfo {
  id: string;
  name: string;
  kafkaVersion: string;
  mode: string;
  environment: string;
  createdAt: string;
  status: string;
  nodeCount: number;
  bootstrapServers?: string;
  clusterId?: string;
