import { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { Users, Search, ChevronLeft, ChevronRight, X, ArrowUp, RefreshCw } from 'lucide-react';
import './Consumers.css';

interface ConsumerGroupSummaryDto {
  groupId: string;
  state: string;
  membersCount: number;
  totalLag: number;
  health: 'HEALTHY' | 'WARNING' | 'INACTIVE' | 'CRITICAL';
  lastUpdated: number;
}

interface PaginatedResponse<T> {
  content: T[];
  page: number;
  size: number;
  totalElements: number;
  totalPages: number;
  hasNext: boolean;
}

interface PartitionLagDto {
  topic: string;
  partition: number;
  currentOffset: number;
  logEndOffset: number;
  lag: number;
}

interface ConsumerGroupMemberDto {
  memberId: string;
  clientId: string;
  host: string;
  partitions: PartitionLagDto[];
}

interface ConsumerGroupDetailDto {
  groupId: string;
  state: string;
  members: ConsumerGroupMemberDto[];
}

export function Consumers() {
  const { id } = useParams<{ id: string }>();
  const [data, setData] = useState<PaginatedResponse<ConsumerGroupSummaryDto> | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [page, setPage] = useState(0);
  const [size] = useState(10);
  const [searchInput, setSearchInput] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState('totalLag'); // Default sort

  // Detail Modal State
  const [selectedGroupId, setSelectedGroupId] = useState<string | null>(null);
  const [detailLoading, setDetailLoading] = useState(false);
  const [detailData, setDetailData] = useState<ConsumerGroupDetailDto | null>(null);

  const fetchGroups = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch(`/api/v1/clusters/${id}/consumer-groups?page=${page}&size=${size}&search=${encodeURIComponent(searchQuery)}&sortBy=${sortBy}`);
      if (!res.ok) {
        const errorData = await res.json().catch(() => ({}));
        throw new Error(errorData.message || `Failed to load consumer groups (HTTP ${res.status})`);
      }
      const json = await res.json();
      setData(json);
    } catch (e: any) {
      console.error(e);
      setError(e.message || 'Failed to load consumer groups');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchGroups();
  }, [id, page, searchQuery, sortBy]);

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setPage(0);
    setSearchQuery(searchInput);
  };

  const handleSort = (column: string) => {
    setSortBy(column);
    setPage(0);
  };

  const handleRowClick = async (groupId: string) => {
    setSelectedGroupId(groupId);
    setDetailLoading(true);
    setDetailData(null);
    try {
      const res = await fetch(`/api/v1/clusters/${id}/consumer-groups/${encodeURIComponent(groupId)}`);
      if (res.ok) {
        setDetailData(await res.json());
      }
    } catch (e) {
      console.error(e);
    } finally {
      setDetailLoading(false);
    }
  };



  return (
    <div className="consumers-tab animate-fade-in">
      <div className="consumers-header">
        <h2 className="cluster-section-heading">Consumer Groups</h2>
        <div className="consumer-groups-toolbar">
          <form className="consumer-search-form" onSubmit={handleSearchSubmit}>
            <label className="consumer-search-field">
              <Search size={16} />
              <input
                type="text"
                placeholder="Search key or value"
                value={searchInput}
                onChange={(event) => setSearchInput(event.target.value)}
              />
            </label>
          </form>
          <button
            type="button"
            className="consumer-refresh-button"
            onClick={fetchGroups}
            disabled={loading}
            aria-label="Refresh consumer groups"
          >
            <RefreshCw className={loading ? 'spin' : ''} size={15} />
          </button>
        </div>
      </div>

      {error && (
        <div className="error-alert" style={{ marginBottom: '1rem' }}>
          {error}
        </div>
      )}

      <div className="table-card">
        {loading && !data ? (
          <div className="empty-state">Loading consumer groups...</div>
        ) : data?.content.length === 0 ? (
          <div className="empty-state">
            <Users size={32} style={{ color: 'var(--text-secondary)' }} />
            <p className="empty-title">No active consumer groups</p>
            <p className="empty-subtitle">There are no consumers matching your search criteria.</p>
          </div>
        ) : (
          <>
            <div style={{ overflowX: 'auto', width: '100%' }}>
              <div className="figma-table" style={{ display: 'flex', flexDirection: 'column', width: '100%' }}>
                {/* Header Row */}
                <div className="figma-table-header" style={{ display: 'flex', flexDirection: 'row', alignItems: 'center', width: '100%', height: '54px', background: '#F9F9F9', borderBottom: '1px solid #CCCCCC', boxSizing: 'border-box' }}>
                  <div style={{ boxSizing: 'border-box', display: 'flex', flexDirection: 'row', alignItems: 'center', padding: '16px', gap: '4px', width: '188.17px', flex: '1 1 188.17px', height: '54px', color: '#332849', fontFamily: 'Satoshi, sans-serif', fontWeight: 500, fontSize: '16px', cursor: 'pointer' }} onClick={() => handleSort('groupId')}>
                    <span>Group ID</span> <ArrowUp size={14} style={{ marginLeft: '4px' }} />
                  </div>
                  <div style={{ boxSizing: 'border-box', display: 'flex', flexDirection: 'row', alignItems: 'center', padding: '16px', gap: '4px', width: '188.17px', flex: '1 1 188.17px', height: '54px', color: '#332849', fontFamily: 'Satoshi, sans-serif', fontWeight: 500, fontSize: '16px', cursor: 'pointer' }} onClick={() => handleSort('state')}>
                    <span>State</span>
                  </div>
                  <div style={{ boxSizing: 'border-box', display: 'flex', flexDirection: 'row', alignItems: 'center', padding: '16px', gap: '4px', width: '188.17px', flex: '1 1 188.17px', height: '54px', color: '#332849', fontFamily: 'Satoshi, sans-serif', fontWeight: 500, fontSize: '16px' }}>
                    <span>Members</span>
                  </div>
                  <div style={{ boxSizing: 'border-box', display: 'flex', flexDirection: 'row', alignItems: 'center', padding: '16px', gap: '4px', width: '188.17px', flex: '1 1 188.17px', height: '54px', color: '#332849', fontFamily: 'Satoshi, sans-serif', fontWeight: 500, fontSize: '16px', cursor: 'pointer' }} onClick={() => handleSort('totalLag')}>
                    <span>Total Lag</span>
                  </div>
                  <div style={{ boxSizing: 'border-box', display: 'flex', flexDirection: 'row', alignItems: 'center', padding: '16px', gap: '4px', width: '188.17px', flex: '1 1 188.17px', height: '54px', color: '#332849', fontFamily: 'Satoshi, sans-serif', fontWeight: 500, fontSize: '16px' }}>
                    <span>Health</span>
                  </div>
                  <div style={{ boxSizing: 'border-box', display: 'flex', flexDirection: 'row', alignItems: 'center', padding: '16px', gap: '4px', width: '188.17px', flex: '1 1 188.17px', height: '54px', color: '#332849', fontFamily: 'Satoshi, sans-serif', fontWeight: 500, fontSize: '16px' }}>
                    <span>Last Updated</span>
                  </div>
                </div>

                {/* Table Body */}
                <div className="figma-table-body" style={{ display: 'flex', flexDirection: 'column' }}>
                  {data?.content.map(g => (
                    <div key={g.groupId} className="figma-table-row table-row-hover clickable" onClick={() => handleRowClick(g.groupId)} style={{ display: 'flex', flexDirection: 'row', alignItems: 'center', width: '100%', height: '52px', background: '#FFFFFF', borderBottom: '1px solid #CCCCCC', boxSizing: 'border-box' }}>
                      <div style={{ boxSizing: 'border-box', display: 'flex', flexDirection: 'row', alignItems: 'center', padding: '14px 16px', gap: '4px', width: '188.17px', flex: '1 1 188.17px', height: '52px', color: '#23252D', fontFamily: 'Satoshi, sans-serif', fontWeight: 500, fontSize: '14px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                        {g.groupId}
                      </div>
                      <div style={{ boxSizing: 'border-box', display: 'flex', flexDirection: 'row', alignItems: 'center', padding: '14px 16px', gap: '4px', width: '188.17px', flex: '1 1 188.17px', height: '52px', color: '#23252D', fontFamily: 'Satoshi, sans-serif', fontWeight: 400, fontSize: '14px' }}>
                        {g.state}
                      </div>
                      <div style={{ boxSizing: 'border-box', display: 'flex', flexDirection: 'row', alignItems: 'center', padding: '14px 16px', gap: '4px', width: '188.17px', flex: '1 1 188.17px', height: '52px', color: '#23252D', fontFamily: 'Satoshi, sans-serif', fontWeight: 400, fontSize: '14px' }}>
                        {g.membersCount}
                      </div>
                      <div style={{ boxSizing: 'border-box', display: 'flex', flexDirection: 'row', alignItems: 'center', padding: '14px 16px', gap: '4px', width: '188.17px', flex: '1 1 188.17px', height: '52px', color: '#23252D', fontFamily: 'Satoshi, sans-serif', fontWeight: 400, fontSize: '14px' }}>
                        {g.totalLag}
                      </div>
                      <div style={{ boxSizing: 'border-box', display: 'flex', flexDirection: 'row', alignItems: 'center', padding: '14px 16px', gap: '4px', width: '188.17px', flex: '1 1 188.17px', height: '52px', color: '#23252D', fontFamily: 'Satoshi, sans-serif', fontWeight: 400, fontSize: '14px' }}>
                        {g.health.charAt(0) + g.health.slice(1).toLowerCase()}
                      </div>
                      <div style={{ boxSizing: 'border-box', display: 'flex', flexDirection: 'row', alignItems: 'center', padding: '14px 16px', gap: '4px', width: '188.17px', flex: '1 1 188.17px', height: '52px', color: '#818181', fontFamily: 'Satoshi, sans-serif', fontWeight: 400, fontSize: '14px' }}>
                        {new Date(g.lastUpdated).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Pagination Controls */}
            {data && data.totalPages > 1 && (
              <div className="pagination">
                <span style={{ fontSize: '0.875rem', color: 'var(--text-secondary)' }}>
                  Showing {page * size + 1} to {Math.min((page + 1) * size, data.totalElements)} of {data.totalElements} results
                </span>
                <div className="pagination-controls">
                  <button
                    className="pagination-btn"
                    disabled={page === 0}
                    onClick={() => setPage(p => p - 1)}
                  >
                    <ChevronLeft size={16} /> Previous
                  </button>
                  <button
                    className="pagination-btn"
                    disabled={!data.hasNext}
                    onClick={() => setPage(p => p + 1)}
                  >
                    Next <ChevronRight size={16} />
                  </button>
                </div>
              </div>
            )}
          </>
        )}
      </div>

      {/* Detail Modal */}
      {selectedGroupId && (
        <div className="modal-overlay" onClick={() => setSelectedGroupId(null)} style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: 'rgba(0, 0, 0, 0.4)',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          zIndex: 1000,
          fontFamily: 'Satoshi, Inter, sans-serif'
        }}>
          <div className="modal-content" onClick={e => e.stopPropagation()} style={{
            background: '#fff',
            borderRadius: '16px',
            width: '100%',
            maxWidth: '780px',
            boxShadow: '0 10px 25px rgba(0,0,0,0.1)',
            overflow: 'hidden',
            padding: 0
          }}>
            {/* Modal Header */}
            <div style={{ padding: '24px 32px 12px 32px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <h3 style={{ margin: 0, fontFamily: 'Satoshi, sans-serif', fontWeight: 600, fontSize: '20px', color: '#332849' }}>Consumer Group Details</h3>
                <button onClick={() => setSelectedGroupId(null)} style={{ background: 'none', border: 'none', cursor: 'pointer', padding: '4px', display: 'flex', alignItems: 'center' }}>
                  <X size={20} color="#94a3b8" />
                </button>
              </div>
              <span style={{ fontSize: '13px', color: '#64748b', display: 'block', marginTop: '2px' }}>{selectedGroupId}</span>
            </div>

            <div className="modal-body" style={{ padding: 0 }}>
              {detailLoading ? (
                <div style={{ padding: '32px', textAlign: 'center', color: '#64748b' }}>Loading details...</div>
              ) : detailData ? (
                <div>
                  {/* Info Cards */}
                  <div style={{ display: 'flex', gap: '16px', padding: '0 32px 24px 32px' }}>
                    <div style={{
                      boxSizing: 'border-box',
                      display: 'flex',
                      flexDirection: 'column',
                      justifyContent: 'center',
                      alignItems: 'flex-start',
                      padding: '16px 20px',
                      gap: '8px',
                      width: '280px',
                      height: '84px',
                      background: '#F9F9FB',
                      border: '1px solid #E2E8F0',
                      borderRadius: '8px'
                    }}>
                      <span style={{ fontSize: '12px', fontWeight: 500, color: '#64748B', textTransform: 'uppercase', letterSpacing: '0.05em' }}>State</span>
                      <span style={{
                        fontSize: '18px',
                        fontWeight: 600,
                        color: detailData.state === 'Stable' ? '#10B981' : '#EF4444'
                      }}>{detailData.state}</span>
                    </div>
                    <div style={{
                      boxSizing: 'border-box',
                      display: 'flex',
                      flexDirection: 'column',
                      justifyContent: 'center',
                      alignItems: 'flex-start',
                      padding: '16px 20px',
                      gap: '8px',
                      width: '280px',
                      height: '84px',
                      background: '#F9F9FB',
                      border: '1px solid #E2E8F0',
                      borderRadius: '8px'
                    }}>
                      <span style={{ fontSize: '12px', fontWeight: 500, color: '#64748B', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Total Members</span>
                      <span style={{ fontSize: '18px', fontWeight: 600, color: '#10B981' }}>{detailData.members.length}</span>
                    </div>
                  </div>

                  {/* Section Title */}
                  <div style={{ padding: '0 32px 12px 32px' }}>
                    <h4 style={{ margin: 0, fontFamily: 'Satoshi, sans-serif', fontWeight: 600, fontSize: '16px', color: '#5B327F' }}>Members & Partitions</h4>
                  </div>

                  {/* Members List */}
                  <div style={{ padding: '0 32px 32px 32px', maxHeight: '420px', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '24px' }}>
                    {detailData.members.length === 0 ? (
                      <p style={{ color: '#64748b', fontSize: '14px', margin: 0 }}>No active members or assigned partitions found for this group.</p>
                    ) : (
                      detailData.members.map((m, i) => (
                        <div key={i} style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                          {/* Member Headers */}
                          <div style={{ display: 'flex', gap: '48px', fontSize: '13px', color: '#332849' }}>
                            <div>
                              <div style={{ fontWeight: 500, color: '#64748B', marginBottom: '4px' }}>Member ID</div>
                              <div style={{ fontFamily: 'monospace' }}>{m.memberId}</div>
                            </div>
                            <div>
                              <div style={{ fontWeight: 500, color: '#64748B', marginBottom: '4px' }}>Client ID</div>
                              <div>{m.clientId}</div>
                            </div>
                            <div>
                              <div style={{ fontWeight: 500, color: '#64748B', marginBottom: '4px' }}>Host</div>
                              <div>{m.host}</div>
                            </div>
                          </div>

                          {/* Partitions Table */}
                          <div style={{ border: '1px solid #E2E8F0', borderRadius: '12px', overflow: 'hidden' }}>
                            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '14px', fontFamily: 'Satoshi, sans-serif' }}>
                              <thead>
                                <tr style={{ background: '#F9F9FB', borderBottom: '1px solid #E2E8F0' }}>
                                  <th style={{ padding: '12px 16px', textAlign: 'left', fontWeight: 500, color: '#332849' }}>Topic</th>
                                  <th style={{ padding: '12px 16px', textAlign: 'left', fontWeight: 500, color: '#332849' }}>Partition</th>
                                  <th style={{ padding: '12px 16px', textAlign: 'left', fontWeight: 500, color: '#332849' }}>Current Offset</th>
                                  <th style={{ padding: '12px 16px', textAlign: 'left', fontWeight: 500, color: '#332849' }}>Lag</th>
                                </tr>
                              </thead>
                              <tbody>
                                {m.partitions.length === 0 ? (
                                  <tr>
                                    <td colSpan={4} style={{ padding: '16px', textAlign: 'center', color: '#64748B' }}>No partitions assigned</td>
                                  </tr>
                                ) : (
                                  m.partitions.map((p, idx) => (
                                    <tr key={`${p.topic}-${p.partition}`} style={{ borderBottom: idx === m.partitions.length - 1 ? 'none' : '1px solid #E2E8F0' }}>
                                      <td style={{ padding: '12px 16px', color: '#332849' }}>{p.topic}</td>
                                      <td style={{ padding: '12px 16px', color: '#332849' }}>{p.partition}</td>
                                      <td style={{ padding: '12px 16px', color: '#332849' }}>
                                        {p.currentOffset === -1 ? 'Unknown' : p.currentOffset.toLocaleString()}
                                      </td>
                                      <td style={{ padding: '12px 16px', fontWeight: p.lag > 0 ? 600 : 400, color: p.lag > 0 ? '#F97316' : '#332849' }}>
                                        {p.lag === -1 ? 'Unknown' : p.lag.toLocaleString()}
                                      </td>
                                    </tr>
                                  ))
                                )}
                              </tbody>
                            </table>
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              ) : (
                <div style={{ padding: '32px', textAlign: 'center', color: '#ef4444' }}>Failed to load group details.</div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { CheckCircle2, Clock, Copy, Loader2, RefreshCw, Server, Terminal, XCircle, RotateCcw, PlayCircle, Trash2, Download, ChevronDown } from 'lucide-react';
import { retryTask, resumeTask, rollbackTask, cleanupTask } from '../lib/api';
import { confirmAction, notifyAction } from '../components/ConfirmDialog';
import './DeploymentLogs.css';

interface Task {
  id: string;
  hostId: string;
  command: string;
  status: string;
  logOutput: string;
  errorMsg: string;
  currentStep?: string;
  failedReason?: string;
  stepLogs?: string; // JSON String from backend representing Map<string, string>
  createdAt: string;
  updatedAt: string;
}

interface ClusterInfo {
  status: string;
}

const activeStatus = (status: string) => ['PENDING', 'RUNNING', 'VALIDATING', 'IN_PROGRESS'].includes(String(status).toUpperCase());

const friendlyFailure = (task: Task) => {
  if (task.failedReason && !task.failedReason.includes('Exception') && task.failedReason.length < 500) return task.failedReason;
  const error = `${task.errorMsg || ''} ${task.failedReason || ''}`.toLowerCase();
  if (error.includes('404') || error.includes('download')) return 'Kafka could not be downloaded. Verify the artifact repository URL and network access from this host.';
  if (error.includes('checksum')) return 'The Kafka package failed its integrity check. Distribute the binary again and retry.';
  if (error.includes('permission denied')) return 'The agent lacks permission to write files or manage the Kafka service.';
  if (error.includes('no space left')) return 'The target host does not have enough disk space.';
  if (error.includes('systemctl') || error.includes('service')) return 'Kafka files were prepared, but the Kafka service could not start.';
  if (error.includes('port') || error.includes('listening')) return 'Kafka did not become reachable on its configured port.';
  return `Deployment stopped during ${task.currentStep || 'an unknown step'}. Review the technical log below.`;
};

const DEPLOYMENT_STEPS = [
  'Validate agent',
  'Validate host prerequisites',
  'Validate package',
  'Download package to agent',
  'Verify checksum',
  'Extract Kafka',
  'Backup old config if exists',
  'Generate config',
  'Format KRaft storage / setup Zookeeper',
  'Create systemd service',
  'Start service',
  'Validate port',
  'Validate Kafka AdminClient connection',
  'Validate cluster health',
  'Mark DB state RUNNING',
];

export function DeploymentLogs() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [cluster, setCluster] = useState<ClusterInfo | null>(null);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [selectedTaskId, setSelectedTaskId] = useState('');
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [copyNotice, setCopyNotice] = useState('');
  const [actionLoading, setActionLoading] = useState(false);
  const [isConsoleMaximized, setIsConsoleMaximized] = useState(false);
  const logBodyRef = useRef<HTMLDivElement>(null);
  const copyNoticeTimerRef = useRef<number | null>(null);

  const fetchTasks = async (manual = false) => {
    if (manual) setRefreshing(true);
    try {
      const [clusterRes, tasksRes] = await Promise.all([
        fetch(`/api/v1/ui/clusters/${id}`, { cache: 'no-store' }),
        fetch(`/api/v1/ui/clusters/${id}/tasks`, { cache: 'no-store' }),
      ]);
      if (clusterRes.ok) setCluster(await clusterRes.json());
      if (tasksRes.ok) {
        const nextTasks: Task[] = await tasksRes.json();
        const availableTasks = Array.isArray(nextTasks) ? nextTasks : [];
        setTasks(availableTasks);
        setSelectedTaskId(current => current && availableTasks.some(task => task.id === current) ? current : availableTasks[0]?.id || '');
      } else {
        throw new Error('Tasks request failed');
      }
    } catch (error) {
      console.error('Failed to load deployment logs', error);
      setTasks([]);
      setSelectedTaskId('');
    } finally {
      setLoading(false);
      if (manual) setRefreshing(false);
    }
  };

  useEffect(() => {
    fetchTasks();
  }, [id]);

  const shouldPoll = tasks.some(task => activeStatus(task.status))
    || ['PENDING', 'RUNNING', 'VALIDATING', 'DELETING'].includes(cluster?.status || '');

  useEffect(() => {
    if (!shouldPoll) return;
    const interval = window.setInterval(fetchTasks, 3000);
    return () => window.clearInterval(interval);
  }, [id, shouldPoll]);

  const selectedTask = tasks.find(task => task.id === selectedTaskId) || tasks[0];

  useEffect(() => {
    if (logBodyRef.current) logBodyRef.current.scrollTop = logBodyRef.current.scrollHeight;
  }, [selectedTask?.logOutput, selectedTask?.stepLogs]);

  useEffect(() => () => {
    if (copyNoticeTimerRef.current !== null) window.clearTimeout(copyNoticeTimerRef.current);
  }, []);

  const handleCopyLogs = async () => {
    if (!selectedTask) return;
    try {
      await navigator.clipboard.writeText(selectedTask.logOutput || selectedTask.errorMsg || '');
      setCopyNotice('Copied to clipboard');
      if (copyNoticeTimerRef.current !== null) window.clearTimeout(copyNoticeTimerRef.current);
      copyNoticeTimerRef.current = window.setTimeout(() => setCopyNotice(''), 2500);
    } catch (error) {
      console.error('Failed to copy deployment logs', error);
      notifyAction('Unable to copy logs to the clipboard.');
    }
  };

  const statusIcon = (status: string) => {
    if (status === 'SUCCESS') return <CheckCircle2 size={15} />;
    if (status === 'FAILED') return <XCircle size={15} />;
    if (activeStatus(status)) return <Loader2 size={15} className="spin" />;
    return <Clock size={15} />;
  };

  if (loading && tasks.length === 0) {
    return <div className="state-center"><Loader2 className="spin" /> Loading deployment logs...</div>;
  }

  if (!selectedTask) {
    return (
      <div className="empty-state deployment-log-empty">
        <Terminal size={32} />
        <h3>No deployment logs</h3>
        <p>No task has been executed for this cluster.</p>
      </div>
    );
  }

  let stepLogsObj: Record<string, string> = {};
  try {
    if (selectedTask.stepLogs) {
      stepLogsObj = JSON.parse(selectedTask.stepLogs);
    }
  } catch (e) {
    console.error("Failed to parse step logs", e);
  }

  const handleRetry = async () => {
    if (!id || !selectedTask) return;
    setActionLoading(true);
    try {
      await retryTask(id, selectedTask.id);
      fetchTasks();
    } catch (e) {
      console.error(e);
      notifyAction("Failed to retry task.");
    } finally {
      setActionLoading(false);
    }
  };

  const handleRollback = async () => {
    if (!id || !selectedTask) return;
    if (!(await confirmAction("Are you sure you want to rollback this deployment? (Services will be stopped but logs and configs remain)"))) return;
    
    setActionLoading(true);
    try {
      await rollbackTask(id, selectedTask.id);
      fetchTasks();
    } catch (e) {
      console.error(e);
      notifyAction("Failed to trigger rollback.");
    } finally {
      setActionLoading(false);
    }
  };

  const handleResume = async () => {
    if (!id || !selectedTask) return;
    setActionLoading(true);
    try {
      await resumeTask(id, selectedTask.id);
      fetchTasks();
    } catch (e) {
      console.error(e);
      notifyAction("Failed to resume task.");
    } finally {
      setActionLoading(false);
    }
  };

  const handleCleanup = async () => {
    if (!id || !selectedTask) return;
    if (!(await confirmAction("Are you sure you want to completely clean up this deployment? (All files and logs on the node will be deleted)"))) return;
    
    setActionLoading(true);
    try {
      await cleanupTask(id, selectedTask.id);
      fetchTasks();
    } catch (e) {
      console.error(e);
      notifyAction("Failed to trigger cleanup.");
    } finally {
      setActionLoading(false);
    }
  };

  const handleDownloadLogs = () => {
    if (!selectedTask) return;
    const content = selectedTask.logOutput || selectedTask.errorMsg || '';
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `tantor-deployment-${selectedTask.id}.log`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const activeStepIndex = DEPLOYMENT_STEPS.indexOf(selectedTask.currentStep || '');
  const isFailed = selectedTask.status === 'FAILED';
  const renderLogs = (logsText: string) => {
    if (!logsText) return 'No output recorded.';
    return logsText.split('\n').map((line, idx) => {
      let className = 'log-line';
      const lowerLine = line.toLowerCase();
      if (lowerLine.includes('completed')) {
        className += ' log-success';
      } else if (lowerLine.includes('failed') || lowerLine.includes('error')) {
        className += ' log-error';
      }
      return <div key={idx} className={className}>{line || ' '}</div>;
    });
  };

  return (
    <div className="deployment-log-view animate-fade-in" style={{ display: 'flex', flexDirection: 'column', gap: '16px', alignSelf: 'stretch' }}>
      
      {/* Title Row with Task output & refresh icon */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%' }}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '2px' }}>
          <h2 style={{ fontFamily: 'Satoshi, sans-serif', fontWeight: 700, fontSize: '16px', lineHeight: '22px', color: '#282F49', margin: 0 }}>Task output</h2>
          <span style={{ fontFamily: 'Satoshi, sans-serif', fontWeight: 400, fontSize: '14px', lineHeight: '19px', color: '#818181' }}>
            {tasks.length} task{tasks.length === 1 ? '' : 's'} recorded
          </span>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <button 
            onClick={handleCopyLogs}
            style={{
              boxSizing: 'border-box',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              padding: '8px',
              width: '40px',
              height: '40px',
              border: '1px solid #CCCCCC',
              borderRadius: '8px',
              background: '#FFFFFF',
              cursor: 'pointer'
            }}
            title="Copy logs"
          >
            <Copy size={16} style={{ color: '#818181' }} />
          </button>
          <button 
            onClick={() => fetchTasks(true)}
            disabled={loading || refreshing}
            style={{
              boxSizing: 'border-box',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              padding: '8px',
              width: '40px',
              height: '40px',
              border: '1px solid #CCCCCC',
              borderRadius: '8px',
              background: '#FFFFFF',
              cursor: 'pointer'
            }}
            title="Refresh"
          >
            <RefreshCw size={16} className={loading || refreshing ? 'spin' : ''} style={{ color: '#818181' }} />
          </button>
        </div>
      </div>

      {copyNotice && (
        <div className="deployment-copy-toast" role="status" aria-live="polite">
          <CheckCircle2 size={16} />
          {copyNotice}
        </div>
      )}

      {/* Task dropdown selector */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '16px', width: '100%' }}>
        <span style={{ fontFamily: 'Satoshi, sans-serif', fontWeight: 700, fontSize: '16px', lineHeight: '22px', color: '#282F49', width: '33px' }}>
          Task
        </span>
        <div style={{ position: 'relative', flexGrow: 1 }}>
          <select 
            id="deployment-task" 
            value={selectedTask.id} 
            onChange={event => setSelectedTaskId(event.target.value)}
            style={{
              boxSizing: 'border-box',
              display: 'flex',
              flexDirection: 'row',
              alignItems: 'center',
              padding: '10px 16px',
              width: '100%',
              height: '40px',
              background: '#FFFFFF',
              border: '1px solid #8E77BB',
              borderRadius: '8px',
              fontFamily: 'Satoshi, sans-serif',
              fontWeight: 400,
              fontSize: '14px',
              color: '#8E77BB',
              appearance: 'none',
              cursor: 'pointer'
            }}
          >
            {tasks.map(task => (
              <option key={task.id} value={task.id}>
                {`${task.command} - ${task.hostId} - ${task.status}`}
              </option>
            ))}
          </select>
          <div style={{ position: 'absolute', right: '16px', top: '10px', pointerEvents: 'none', color: '#8E77BB' }}>
            <ChevronDown size={20} />
          </div>
        </div>
      </div>

      {/* Metadata Table */}
      <div style={{
        boxSizing: 'border-box',
        display: 'flex',
        flexDirection: 'column',
        width: '100%',
        border: '1px solid #CCCCCC',
        borderRadius: '8px',
        overflow: 'hidden'
      }}>
        {/* Table Header */}
        <div style={{ display: 'flex', background: '#F9F9F9', borderBottom: '1px solid #CCCCCC', height: '54px', alignItems: 'center' }}>
          <div style={{ width: '56px', padding: '16px', display: 'flex', alignItems: 'center', justifyContent: 'center' }} />
          <div style={{ flex: 1, padding: '16px', fontFamily: 'Satoshi, sans-serif', fontWeight: 500, fontSize: '16px', color: '#332849' }}>Status</div>
          <div style={{ flex: 1, padding: '16px', fontFamily: 'Satoshi, sans-serif', fontWeight: 500, fontSize: '16px', color: '#332849' }}>Host</div>
          <div style={{ flex: 1, padding: '16px', fontFamily: 'Satoshi, sans-serif', fontWeight: 500, fontSize: '16px', color: '#332849' }}>Started</div>
          <div style={{ flex: 1, padding: '16px', fontFamily: 'Satoshi, sans-serif', fontWeight: 500, fontSize: '16px', color: '#332849' }}>Updated</div>
        </div>
        {/* Table Body Row */}
        <div 
          style={{ display: 'flex', background: '#FFFFFF', height: '52px', alignItems: 'center', cursor: 'default' }}
        >
          <div style={{ width: '56px', padding: '14px 16px', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#818181' }}>
            {statusIcon(selectedTask.status)}
          </div>
          <div style={{ flex: 1, padding: '14px 16px', fontFamily: 'Satoshi, sans-serif', fontWeight: 400, fontSize: '14px', color: '#23252D' }}>
            {selectedTask.status}
          </div>
          <div style={{ flex: 1, padding: '14px 16px', fontFamily: 'Satoshi, sans-serif', fontWeight: 400, fontSize: '14px', color: '#23252D', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }} title={selectedTask.hostId}>
            {selectedTask.hostId}
          </div>
          <div style={{ flex: 1, padding: '14px 16px', fontFamily: 'Satoshi, sans-serif', fontWeight: 400, fontSize: '14px', color: '#23252D' }}>
            {new Date(selectedTask.createdAt).toLocaleString()}
          </div>
          <div style={{ flex: 1, padding: '14px 16px', fontFamily: 'Satoshi, sans-serif', fontWeight: 400, fontSize: '14px', color: '#23252D' }}>
            {new Date(selectedTask.updatedAt).toLocaleString()}
          </div>
        </div>
      </div>

      {/* Full width Log CodeBlock console */}
      <div style={{ display: 'flex', flexDirection: 'column', width: '100%' }}>
        {/* Dark purple header bar */}
        <div style={{
          display: 'flex',
          justifyContent: 'flex-end',
          alignItems: 'center',
          padding: '10px 20px',
          height: '44px',
          background: '#332849',
          borderRadius: '8px 8px 0px 0px'
        }}>
          <button 
            onClick={() => setIsConsoleMaximized(!isConsoleMaximized)}
            style={{
              background: 'none',
              border: 'none',
              cursor: 'pointer',
              color: '#FFFFFF',
              display: 'flex',
              alignItems: 'center',
              padding: 0
            }}
            title={isConsoleMaximized ? "Collapse logs" : "Expand logs"}
          >
            {isConsoleMaximized ? (
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{ color: '#FFFFFF' }}>
                <path d="M13 7v4h4" />
                <path d="M11 17v-4H7" />
              </svg>
            ) : (
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{ color: '#FFFFFF' }}>
                <path d="M17 11V7H13" />
                <path d="M13 15V11H9" />
              </svg>
            )}
          </button>
        </div>
        
        {/* Log body */}
        <div style={{
          boxSizing: 'border-box',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'flex-start',
          padding: '20px',
          width: '100%',
          minHeight: isConsoleMaximized ? '650px' : '245px',
          maxHeight: isConsoleMaximized ? 'none' : '400px',
          overflowY: 'auto',
          background: '#000000',
          borderRadius: '0px 0px 16px 16px'
        }} ref={logBodyRef}>
          <div className="logs-text" style={{
            width: '100%',
            fontFamily: 'Source Code Pro, monospace',
            fontSize: '14px',
            lineHeight: '20px',
            color: '#FFFFFF',
            whiteSpace: 'pre-wrap',
            wordBreak: 'break-all'
          }}>
            {renderLogs(selectedTask.logOutput || selectedTask.errorMsg || '')}
          </div>
        </div>
      </div>

      {/* Action buttons if failed */}
      {isFailed && selectedTask.command === 'INSTALL_KAFKA' && (
        <div className="deployment-action-bar">
           <button className="btn-primary" onClick={handleRetry} disabled={actionLoading}>
             {actionLoading ? <Loader2 size={16} className="spin" /> : <RefreshCw size={16} />}
             Retry
           </button>
           <button className="btn-secondary" onClick={handleResume} disabled={actionLoading}>
             {actionLoading ? <Loader2 size={16} className="spin" /> : <PlayCircle size={16} />}
             Resume
           </button>
           <button className="btn-warning" onClick={handleRollback} disabled={actionLoading}>
             {actionLoading ? <Loader2 size={16} className="spin" /> : <RotateCcw size={16} />}
             Rollback
           </button>
           <button className="btn-danger" onClick={handleCleanup} disabled={actionLoading}>
             {actionLoading ? <Loader2 size={16} className="spin" /> : <Trash2 size={16} />}
             Cleanup
           </button>
           <button className="btn-secondary" onClick={handleDownloadLogs}>
             <Download size={16} /> Download Logs
           </button>
        </div>
      )}

      {/* Technical details if error */}
      {selectedTask.errorMsg && (
        <div className="deployment-task-error">
          <strong>What happened</strong>
          <span>{friendlyFailure(selectedTask)}</span>
          {selectedTask.currentStep && <small>Failed step: {selectedTask.currentStep}</small>}
          <details>
            <summary>Technical error</summary>
            <pre>{selectedTask.errorMsg}</pre>
          </details>
        </div>
      )}



    </div>
  );
}

