                  display: 'flex',
                  alignItems: 'center',
                  gap: '8px',
                  background: '#F8FAFC',
                  border: '1px solid #E2E8F0',
                  borderRadius: '8px',
                  padding: '8px 12px',
                  cursor: 'pointer',
                  userSelect: 'none',
                  height: '40px',
                  boxSizing: 'border-box'
